        if (!today.equals(store.today(id))) {
            before.people().values().forEach(figures -> audit.record("SNAPSHOT sheet=" + id + " by=" + request.user()
                    + " name=" + figures.name() + " due-total=" + figures.dueTotal()));
            claims.unlockAll(id);
        }
        store.setToday(id, today);
    }
}
